lemma extractOne_sub_add {f : SubRowLensType γ} {k : ℕ}
    (hf : ∑ x ∈ f.1.support, f.1 x = k + 1) :
    f.1 - extractOne hf + extractOne hf = f.1

lemma extractOne_le_sub {f : SubRowLensType γ} {k : ℕ}
    (hf : ∑ x ∈ f.1.support, f.1 x = k + 1) : ∀ i, extractOne hf i ≤
    (γ.sub (f.1 - extractOne hf)).rowLen' i

lemma extractOne_sum_support {f : SubRowLensType γ} {k : ℕ}
    (hf : ∑ x ∈ f.1.support, f.1 x = k + 1) :
    ∑ x ∈ (extractOne hf).support, extractOne hf x = 1

lemma extractOne_sub_sum_support {f : SubRowLensType γ} {k : ℕ}
    (hf : ∑ x ∈ f.1.support, f.1 x = k + 1) :
    ∑ x ∈ (f.1 - extractOne hf).support, (f.1 - extractOne hf) x = k

lemma sub_extractOne_eq_sub {f : SubRowLensType γ} {k : ℕ}
    (hf : ∑ x ∈ f.1.support, f.1 x = k + 1) : γ.sub f.1 =
    (γ.sub (f.1 - extractOne hf)).sub (extractOne hf)

@[simp]
lemma hookDiagram_cells {n : ℕ} (h : n > 0) :
    (hookDiagram (n + 1)).cells = (horizontalDiagram n).cells ∪ {(1, 0)}

lemma entry_le_max {γ : YoungDiagram} {T : SemistandardYoungTableau γ} {i j : ℕ}
    (hTc : T.content.toList ≠ []) :
    T i j ≤ T.content.toList.max hTc

theorem map_twoRow_eq_row2_sub_one {γ : YoungDiagram} {content row2 : Multiset ℕ}
    {hr0 : γ.rowLen 0 = content.card - row2.card}
    {hr1 : γ.rowLen 1 = row2.card} {hc0 : γ.colLen 0 = 2}
    {hrc : row2 ≤ content}
    {h : ∀ i : ℕ, (hi : i < row2.card) → (∀ r ∈ row2, r >
      ((content - row2).sort (· ≤ ·))[i]'(lt_sub_sort_length hrc hr0 hr1 hi))} :
    Multiset.map (fun x ↦ (twoRowTableau hr0 hr1 hc0 hrc h) x.1 x.2 - 1)
    (Multiset.filter (fun x ↦ x.1 = 1) γ.cells.val) =
    Multiset.map (· - 1) row2

lemma eq_horizontalSSYT_content {n : ℕ}
    (T : SemistandardYoungTableau γ) (h : γ = horizontalDiagram n) :
    T.entry = (horizontalSSYT (T.content)).entry

lemma eq_horizontalSSYT_content' {n : ℕ}
    (T : SemistandardYoungTableau (horizontalDiagram n)) :
    T.entry = (horizontalSSYT (T.content)).entry

lemma T10_mem_fromCounts_remove {μ : Multiset ℕ} {T : SemistandardYoungTableau (hookDiagram μ.sum)}
    (h : T.content = μ.fromCounts) (hμ : μ.sum ≥ 2) :
    T 1 0 ∈ μ.fromCounts.remove 0

lemma find_max_cell_start_eq_zero {γ : YoungDiagram}
    (T : SemistandardYoungTableau γ) (hTc : T.content.toList ≠ []) {i : ℕ}
    (h : ∀ x ∈ T.content, x = 0) :
    Nat.find (exists_max_cell_start T i hTc) = 0

lemma entry_find_eq_max {γ : YoungDiagram} {T : SemistandardYoungTableau γ}
    (i : ℕ) (hT : T.content.toList ≠ []) (h : (i, Nat.find (exists_max_cell_start T i hT)) ∈ γ) :
    T i (Nat.find (exists_max_cell_start T i hT)) = T.content.toList.max hT

proof:
