lemma zero_zero_mem_of_dominates (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ μ.sort (· ≥ ·)) (hμ : μ ≠ 0) (h0 : 0 ∉ μ) :
    (0, 0) ∈ γ

lemma min_le_jth_rowLen' (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ μ.sort (· ≥ ·)) (hμ : μ.toList ≠ []) (h0 : 0 ∉ μ) :
    μ.toList.min hμ ≤ γ.rowLen' (jth γ hμ)

lemma jth_lt_colLen (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ μ.sort (· ≥ ·)) (hμ : μ.toList ≠ []) (h0 : 0 ∉ μ) :
    jth γ hμ < γ.colLen 0

lemma sub_max_fun_le_rowLen' (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ (μ.sort (· ≥ ·))) (hμ : μ.toList ≠ []) (h0 : 0 ∉ μ) (i : ℕ) :
    sub_max_fun γ hμ i ≤ γ.rowLen' i

lemma rowLen'_le_rowLen'_sub_max_fun (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ (μ.sort (· ≥ ·))) (hμ : μ.toList ≠ []) (h0 : 0 ∉ μ) (i : ℕ) :
    γ.rowLen' (i + 1) ≤ γ.rowLen' i - sub_max_fun γ hμ i

lemma sub_max_fun_support_finite (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ (μ.sort (· ≥ ·))) (hμ : μ.toList ≠ []) (h0 : 0 ∉ μ) :
    Finite {n : ℕ | (n = (jth γ hμ) ∧ (μ.toList.min hμ) > γ.rowLen' ((jth γ hμ) + 1))
    ∨ (n > (jth γ hμ) ∧ γ.rowLen' n > γ.rowLen' (n + 1) ∧ n < γ.colLen 0)}

lemma sub_max_support_sum (γ : YoungDiagram) {μ : Multiset ℕ}
    (hd : γ.rowLens ⊵ (μ.sort (· ≥ ·))) (hμ : μ.toList ≠ []) (h0 : 0 ∉ μ) :
    ∑ x ∈ (sub_max γ hd hμ h0).1.support, (sub_max γ hd hμ h0).1 x = μ.toList.min hμ

lemma rowLen_ofRowLens_eq_zero {L : List ℕ} {hL : L.SortedGE} {i : ℕ}
    (hp : ∀ x ∈ L, 0 < x) (hi : ¬i < L.length) :
    (ofRowLens L hL).rowLen i = 0

theorem entry_zero_of_lt_max_el (T : SemistandardYoungTableau γ) {μ : Multiset ℕ}
    (hμ : μ.toList ≠ []) (hc : T.content = μ.fromCounts) {j : ℕ}
    (hj : j < μ.toList.max hμ) : T 0 j = 0

theorem lt_max_el_of_entry_zero (T : SemistandardYoungTableau γ) {μ : Multiset ℕ}
    (hμ : μ.toList ≠ []) (hc : T.content = μ.fromCounts) {i j : ℕ} (hij : (i, j) ∈ γ)
    (h : T i j = 0) : i = 0 ∧ j < μ.toList.max hμ

lemma sum_support_gt_one {f : ℕ →₀ ℕ}
    (h : f.support.card ≥ 2 ∨ ∃ a, f a > 1) :
    ∑ x ∈ f.support, f x > 1

lemma horizontal_tail_of_eq_min' {p : γ.hookPath} (hp : p.path.length > 1) {s : Finset ℕ}
    (hs : p.horizontal = s) (hs0 : s.Nonempty) (h : p.path[1].1 = s.min' hs0) :
    p.tail.horizontal = s

lemma horizontal_tail_of_ne_min' {p : γ.hookPath} (hp : p.path.length > 1) {s : Finset ℕ}
    (hs : p.horizontal = s) (hs0 : s.Nonempty) (h : p.path[1].1 ≠ s.min' hs0) :
    p.tail.horizontal = s \ {s.min' hs0}

lemma vertical_tail_of_eq_min' {p : γ.hookPath} (hp : p.path.length > 1) {t : Finset ℕ}
    (ht : p.vertical = t) (ht0 : t.Nonempty) (h : p.path[1].2 = t.min' ht0) :
    p.tail.vertical = t

lemma vertical_tail_of_ne_min' {p : γ.hookPath} (hp : p.path.length > 1) {t : Finset ℕ}
    (ht : p.vertical = t) (ht0 : t.Nonempty) (h : p.path[1].2 ≠ t.min' ht0) :
    p.tail.vertical = t \ {t.min' ht0}

lemma cons_horizontal_of_mem_vertical (p : γ.hookPath) {x : ℕ × ℕ}
    (hx : p.path.head p.ne_nil ∈ γ.hook x) (hx' : x ≠ p.path.head p.ne_nil)
    (hxh : x.2 ∈ p.vertical) :
    (p.cons hx hx').horizontal = p.horizontal ∪ {x.1}

lemma cons_vertical_of_mem_horizontal (p : γ.hookPath) {x : ℕ × ℕ}
    (hx : p.path.head p.ne_nil ∈ γ.hook x) (hx' : x ≠ p.path.head p.ne_nil)
    (hxh : x.1 ∈ p.horizontal) :
    (p.cons hx hx').vertical = p.vertical ∪ {x.2}

lemma downHookPath_horizontal {x : ℕ × ℕ} (hx : x ∈ γ.corners) {t : Finset ℕ}
    (htx : t ∈ (Finset.range x.2).powerset) :
    (downHookPath hx htx).1.horizontal = ∅

lemma downHookPath_vertical {x : ℕ × ℕ} (hx : x ∈ γ.corners) {t : Finset ℕ}
    (htx : t ∈ (Finset.range x.2).powerset) :
    (downHookPath hx htx).1.vertical = t

lemma leftHookPath_horizontal {x : ℕ × ℕ} (hx : x ∈ γ.corners) {s : Finset ℕ}
    (hsx : s ∈ (Finset.range x.1).powerset) :
    (leftHookPath hx hsx).1.horizontal = s

lemma leftHookPath_vertical {x : ℕ × ℕ} (hx : x ∈ γ.corners) {s : Finset ℕ}
    (hsx : s ∈ (Finset.range x.1).powerset) :
    (leftHookPath hx hsx).1.vertical = ∅

lemma setOf_horizontal_empty_eq_down {x : ℕ × ℕ} (hx : x ∈ γ.corners) {t : Finset ℕ}
    (htx : t ∈ (Finset.range x.2).powerset) :
    {p : γ.cornerHookPath | p.1.horizontal = ∅ ∧ p.1.vertical = t ∧
    p.1.path.getLast p.1.ne_nil = x} = {downHookPath hx htx}

lemma setOf_vertical_empty_eq_left {x : ℕ × ℕ} (hx : x ∈ γ.corners) {s : Finset ℕ}
    (hsx : s ∈ (Finset.range x.1).powerset) :
    {p : γ.cornerHookPath | p.1.horizontal = s ∧ p.1.vertical = ∅ ∧
    p.1.path.getLast p.1.ne_nil = x} = {leftHookPath hx hsx}

lemma notMem_path_of_mem_hook {p : γ.hookPath} {x : ℕ × ℕ}
    (hx : x ∈ γ.hook (p.path.getLast p.ne_nil)) (hx' : x ≠ p.path.getLast p.ne_nil) :
    x ∉ p.path

lemma Finset.card_le_card_of_surjective {α β : Type*} {s : Finset α} {t : Finset β} {f : ↥s → ↥t}
    (hf : Function.Surjective f) :
    t.card ≤ s.card

lemma eq_min'_iff_ne_min' {p : γ.hookPath} (hp : p.path.length > 1) {s t : Finset ℕ}
    (hs : p.horizontal = s) (ht : p.vertical = t) (hs0 : s.Nonempty) (ht0 : t.Nonempty) :
    p.path[1].1 = s.min' hs0 ↔ p.path[1].2 ≠ t.min' ht0

private lemma aux_sort_getElem_lt {n : ℕ} {t : Finset ℕ}
    (htx : t ∈ (Finset.range n).powerset) (i : ℕ) (hi : i < (t.sort (· ≤ ·)).length) :
    (t.sort (· ≤ ·))[i] ≤ n

private lemma aux_ite_sort_mem1 {x : ℕ × ℕ} (hx : x ∈ γ.corners) {t : Finset ℕ}
    (htx : t ∈ (Finset.range x.2).powerset) (i : ℕ) :
    (if h : i < t.card then (x.1, (t.sort (· ≤ ·))[i]'(by simpa)) else x) ∈ γ

private lemma aux_ite_sort_mem2 {x : ℕ × ℕ} (hx : x ∈ γ.corners) {s : Finset ℕ}
    (hsx : s ∈ (Finset.range x.1).powerset) (i : ℕ) :
    (if h : i < s.card then ((s.sort (· ≤ ·))[i]'(by simpa), x.2) else x) ∈ γ

lemma downHookPath_getLast {x : ℕ × ℕ} (hx : x ∈ γ.corners) {t : Finset ℕ}
    (htx : t ∈ (Finset.range x.2).powerset) :
    (downHookPath hx htx).1.path.getLast (downHookPath hx htx).1.ne_nil = x

lemma leftHookPath_getLast {x : ℕ × ℕ} (hx : x ∈ γ.corners) {s : Finset ℕ}
    (hsx : s ∈ (Finset.range x.1).powerset) :
    (leftHookPath hx hsx).1.path.getLast (leftHookPath hx hsx).1.ne_nil = x
